#include <stdio.h>
#include <stdlib.h>

#define MAX_NODES 64

static long value[MAX_NODES];
static int next[MAX_NODES];
static int head = -1;   // index of first node, -1 means empty list
static int used = 0;    // number of nodes currently stored

int main(int argc, char **argv) {
    head = -1;
    used = 0;

    /* Process up to 64 integer arguments */
    int limit = argc - 1;               // number of arguments after program name
    if (limit > MAX_NODES) {
        limit = MAX_NODES;              // silently ignore excess arguments
    }

    for (int i = 0; i < limit; ++i) {
        long v = strtol(argv[i + 1], NULL, 10);
        int idx = used;                 // index for the new node
        value[idx] = v;
        next[idx] = -1;

        if (head == -1 || value[head] > v) {
            /* Insert at the beginning */
            next[idx] = head;
            head = idx;
        } else {
            /* Find insertion point to keep list sorted (ascending) */
            int cur = head;
            while (next[cur] != -1 && value[next[cur]] <= v) {
                cur = next[cur];
            }
            next[idx] = next[cur];
            next[cur] = idx;
        }
        ++used;
    }

    if (head == -1) {
        puts("EMPTY");
        return 0;
    }

    int cur = head;
    int first = 1;
    while (cur != -1) {
        if (!first) {
            putchar(' ');
        }
        printf("%ld", value[cur]);
        first = 0;
        cur = next[cur];
    }
    putchar('\n');
    return 0;
}
